import { useEffect, useRef, useState } from 'react';
import { useSelector } from 'react-redux';

import { Note, selectSoundingNotes } from 'app/services/NotesService';

import { MAX_PITCH_BEND_CENTS, setNotesPitchBend } from '..';

export const useTrackpadPitchBend = () => {
  const soundingNotes = useSelector(selectSoundingNotes);
  const notesRef = useRef<Note[]>([]);
  const bendRef = useRef(0);
  const resetRef = useRef(() => {});
  const cursorRef = useRef<{ x: number; y: number }>();
  const anchorRef = useRef<{ x: number; y: number }>();
  const [indicator, setIndicator] = useState({
    x: 0,
    y: 0,
    cents: 0,
    visible: false,
  });

  useEffect(() => {
    notesRef.current = soundingNotes;
    if (!soundingNotes.length) {
      resetRef.current();
    } else {
      setNotesPitchBend(soundingNotes, bendRef.current);
      if (cursorRef.current) {
        anchorRef.current ??= cursorRef.current;
        setIndicator({
          ...anchorRef.current,
          cents: bendRef.current,
          visible: true,
        });
      }
    }
  }, [soundingNotes]);

  useEffect(() => {
    let gestureAxis: 'x' | 'y' | undefined;

    const reset = () => {
      bendRef.current = 0;
      anchorRef.current = undefined;
      gestureAxis = undefined;
      setNotesPitchBend(notesRef.current, 0);
      setIndicator(previous => ({ ...previous, cents: 0, visible: false }));
    };
    resetRef.current = reset;

    const handleMouseMove = (event: MouseEvent) => {
      cursorRef.current = { x: event.clientX, y: event.clientY };
      if (!notesRef.current.length) {
        return;
      }
      anchorRef.current ??= cursorRef.current;
      const deltaX = event.clientX - anchorRef.current.x;
      const deltaY = event.clientY - anchorRef.current.y;

      if (deltaX || deltaY) {
        // Keep diagonal gestures stable when small inaccuracies change the dominant axis.
        if (!gestureAxis) {
          gestureAxis = Math.abs(deltaX) >= Math.abs(deltaY) ? 'x' : 'y';
        } else if (Math.abs(deltaY) > Math.abs(deltaX) * 2) {
          gestureAxis = 'y';
        } else if (Math.abs(deltaX) > Math.abs(deltaY) * 2) {
          gestureAxis = 'x';
        }
        const movement = gestureAxis === 'x' ? deltaX : -deltaY;

        // Measure from the fixed origin so returning to the centre always restores pitch.
        bendRef.current = Math.max(
          -MAX_PITCH_BEND_CENTS,
          Math.min(MAX_PITCH_BEND_CENTS, movement * 3),
        );
      } else {
        bendRef.current = 0;
        gestureAxis = undefined;
      }
      setNotesPitchBend(notesRef.current, bendRef.current);
      setIndicator({
        ...anchorRef.current,
        cents: bendRef.current,
        visible: true,
      });
    };

    const hideIndicator = () => {
      setIndicator(previous => ({ ...previous, visible: false }));
      cursorRef.current = undefined;
      gestureAxis = undefined;
    };

    const handleVisibilityChange = () => {
      if (document.hidden) {
        hideIndicator();
      }
    };

    window.addEventListener('mousemove', handleMouseMove, { passive: true });
    window.addEventListener('blur', hideIndicator);
    document.documentElement.addEventListener('mouseleave', hideIndicator);
    document.addEventListener('visibilitychange', handleVisibilityChange);

    return () => {
      reset();
      resetRef.current = () => {};
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('blur', hideIndicator);
      document.documentElement.removeEventListener('mouseleave', hideIndicator);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, []);

  return indicator;
};
