import { createSelector } from '@reduxjs/toolkit';

import { RootState } from 'app/services/types';

import { initialState } from '.';

const selectSlice = (state: RootState) => state.notes || initialState;

export const selectNotes = createSelector([selectSlice], state => state);

export const selectSoundingNotes = createSelector(
  [selectSlice],
  state => state.soundingNotes,
);
