import { ChordStem } from './chordLayout';
import { StaffEvent, getRhythm } from './notation';

export const StaffNote = ({
  event,
  x,
  y,
  bpm,
  stem,
  dotOffset,
  stepY,
}: {
  event: StaffEvent;
  x: number;
  y: number;
  bpm: number;
  stem?: ChordStem;
  dotOffset: number;
  stepY: (step: number) => number;
}) => {
  const { note, duration, headOffset, accidentalColumn, accidental } = event;
  const { hollow, stem: hasStem, dotted } = getRhythm(duration, bpm);
  const cx = x + headOffset;
  const label = `${note}, ${
    duration === undefined ? 'held' : `${duration} ms`
  }`;
  return (
    <g role="img" aria-label={label} data-note={note} data-duration={duration}>
      <title>{label}</title>
      {accidental && (
        <text
          x={x - 15 - accidentalColumn * 13}
          y={y + 5}
          fontSize="19"
          textAnchor="middle"
        >
          {accidental}
        </text>
      )}
      {stem && (
        <g data-chord-stem="true">
          <line
            x1={x + stem.x}
            x2={x + stem.x}
            y1={stepY(stem.startStep)}
            y2={stepY(stem.endStep)}
            stroke="currentColor"
            strokeWidth="1.3"
          />
          {Array.from({ length: stem.flags }, (_, i) => {
            const direction = stem.down ? -1 : 1;
            const tip = stepY(stem.endStep) + direction * i * 6;
            return (
              <path
                key={i}
                data-note-flag="true"
                d={`M ${x + stem.x} ${tip} c 2 ${direction * 5} 10 ${
                  direction * 6
                } 10 ${direction * 13} c 0 ${direction * 3} -1 ${
                  direction * 5
                } -3 ${direction * 7}`}
                fill="none"
                stroke="currentColor"
                strokeWidth="1.8"
                strokeLinecap="round"
              />
            );
          })}
        </g>
      )}
      <ellipse
        cx={cx}
        cy={y}
        rx={hasStem ? 5.5 : 7}
        ry="3.7"
        transform={`rotate(-25 ${cx} ${y})`}
        fill={hollow ? 'var(--staff-background)' : 'currentColor'}
        stroke="currentColor"
        strokeWidth="1.5"
      />
      {dotted && (
        <circle cx={x + dotOffset} cy={y - 2} r="1.7" fill="currentColor" />
      )}
      {duration === undefined && (
        <circle
          cx={cx}
          cy={y}
          r="10"
          fill="none"
          stroke="currentColor"
          opacity="0.4"
        />
      )}
    </g>
  );
};
