import { readPreferences, writePreferences } from 'utils/preferences';

export const AUDIO_ROUTING_KEY = 'qwertophone.audio-routing.v1';

export interface AudioRoutingPreferences {
  live: boolean;
  inputDeviceId: string;
  inputChannel: number;
  liveOutputDeviceId: string | null;
  instrumentOutputDeviceId: string;
  audioConnected: boolean;
  monitoringEnabled: boolean | null;
}

export const loadAudioRouting = (): AudioRoutingPreferences => {
  const saved = readPreferences(AUDIO_ROUTING_KEY);
  return {
    live: saved.live === true,
    audioConnected: saved.audioConnected === true,
    monitoringEnabled:
      typeof saved.monitoringEnabled === 'boolean'
        ? saved.monitoringEnabled
        : null,
    inputDeviceId:
      typeof saved.inputDeviceId === 'string' ? saved.inputDeviceId : '',
    inputChannel:
      typeof saved.inputChannel === 'number' &&
      Number.isInteger(saved.inputChannel) &&
      saved.inputChannel >= 0 &&
      saved.inputChannel < 32
        ? saved.inputChannel
        : 0,
    liveOutputDeviceId:
      typeof saved.liveOutputDeviceId === 'string'
        ? saved.liveOutputDeviceId
        : null,
    instrumentOutputDeviceId:
      typeof saved.instrumentOutputDeviceId === 'string'
        ? saved.instrumentOutputDeviceId
        : '',
  };
};

export const saveAudioRouting = (changes: Partial<AudioRoutingPreferences>) =>
  writePreferences(AUDIO_ROUTING_KEY, { ...loadAudioRouting(), ...changes });
