import { createSelector } from '@reduxjs/toolkit';
import { useEffect, useState } from 'react';
import { useStore } from 'react-redux';

import { selectMelodies } from 'app/services/MelodiesService';
import { selectNotes, selectSoundingNotes } from 'app/services/NotesService';
import { RootState } from 'app/services/types';

import { NoteFlight, RELEASE_LIFETIME } from './flight';

const MAX_FLIGHTS = 160;

export const selectFlyingSoundingNotes = createSelector(
  [selectSoundingNotes, selectNotes, selectMelodies],
  (live, { melody }, { soundingNoteIndices }) =>
    Array.from(
      new Set([
        ...live,
        ...soundingNoteIndices.flatMap(index =>
          melody.notes[index] ? [melody.notes[index].note] : [],
        ),
      ]),
    ),
);

export const useFlyingNotes = () => {
  const store = useStore<RootState>();
  const [snapshot, setSnapshot] = useState<{
    flights: NoteFlight[];
    now: number;
  }>({ flights: [], now: 0 });

  useEffect(() => {
    let flights: NoteFlight[] = [];
    let previous: ReturnType<typeof selectSoundingNotes> = [];
    let nextId = 0;
    let frame: number | undefined;

    const tick = () => {
      frame = undefined;
      const now = performance.now();
      const visible = flights.filter(
        flight =>
          flight.releasedAt === undefined ||
          now - flight.releasedAt < RELEASE_LIFETIME,
      );
      if (visible.length !== flights.length) flights = visible;
      setSnapshot({ flights, now });
      if (flights.length) frame = requestAnimationFrame(tick);
    };

    // Subscribe to note transitions directly, so a short tap between animation
    // frames still launches a note, even when React batches press and release.
    const sync = () => {
      const sounding = selectFlyingSoundingNotes(store.getState());
      if (sounding === previous) return;
      const now = performance.now();
      flights = flights.map(flight =>
        flight.releasedAt === undefined && !sounding.includes(flight.note)
          ? { ...flight, releasedAt: now }
          : flight,
      );
      sounding.forEach(note => {
        if (!previous.includes(note))
          flights.push({ id: ++nextId, note, startedAt: now });
      });
      previous = sounding;
      if (flights.length > MAX_FLIGHTS) {
        const held = flights.filter(flight => flight.releasedAt === undefined);
        const released = flights.filter(
          flight => flight.releasedAt !== undefined,
        );
        flights = [
          ...released.slice(-Math.max(1, MAX_FLIGHTS - held.length)),
          ...held,
        ];
      }
      setSnapshot({ flights, now });
      if (flights.length && frame === undefined)
        frame = requestAnimationFrame(tick);
    };

    const unsubscribe = store.subscribe(sync);
    sync();
    return () => {
      unsubscribe();
      if (frame !== undefined) cancelAnimationFrame(frame);
    };
  }, [store]);

  return snapshot;
};
