import {
  InstrumentEffects,
  defaultEffects,
} from 'app/services/EffectsService/settings';
import {
  TimeSignature,
  getBeatsPerMeasure,
} from 'app/services/MelodiesService/meter';
import { METRONOME_METERS } from 'app/services/MetronomeService/rhythm';

import { DrumPattern, DrumTrack, emptyPattern } from './patterns';
import { DrumSample } from './samples';

const GROOVES = [
  { id: 'steady', label: 'Ровный грув' },
  { id: 'dance', label: 'Танцевальный' },
  { id: 'broken', label: 'Ломаный бит' },
  { id: 'funk', label: 'Фанк' },
  { id: 'percussion', label: 'Перкуссионный' },
] as const;
const FINISHES = ['Комната', 'Тёплый', 'Ритмичное эхо', 'Мягкий хорус'];
const DRUM_PALETTE = [
  [35, 36],
  [37, 38, 39, 40],
  [42, 44, 69, 70],
  [46, 53, 59, 81],
  [41, 43, 45, 47, 48, 56, 60, 61, 62, 63, 64, 67, 68, 75, 76, 77],
];
const PERCUSSION_PALETTE = [
  [35, 36, 64],
  [37, 62, 75],
  [69, 70, 80],
  [67, 68, 81],
  [60, 61, 63, 65, 66, 71, 72, 76, 77, 78, 79],
];

export interface GeneratedDrumBeat {
  pattern: DrumPattern;
  samples: Record<DrumTrack, DrumSample>;
  effects: InstrumentEffects;
  description: string;
}

// Random choices vary a shared groove, rather than flipping independent cells.
export const createRandomDrumBeat = (
  tracks: DrumTrack[],
  meter: TimeSignature,
  bpm: number,
  random: () => number = Math.random,
): GeneratedDrumBeat => {
  const pick = <T>(values: readonly T[]): T =>
    values[Math.floor(random() * values.length)];
  const between = (min: number, max: number) =>
    min + Math.floor(random() * (max - min + 1));
  const chance = (probability: number) => random() < probability;
  const groove = pick(GROOVES);
  const finish = pick(FINISHES);
  const { groups, unit } = METRONOME_METERS[meter];
  const unitSteps = 16 / unit;
  const steps = getBeatsPerMeasure(meter) * 4;
  const groupStarts: number[] = [];
  let groupStart = 0;
  groups.forEach(count => {
    groupStarts.push(groupStart);
    groupStart += count * unitSteps;
  });
  const pulses =
    unit === 8
      ? groupStarts.map((start, index) => ({
          start,
          length: groups[index] * unitSteps,
        }))
      : Array.from({ length: steps / 4 }, (_, index) => ({
          start: index * 4,
          length: 4,
        }));
  const pattern = emptyPattern(tracks);
  const samples: Record<DrumTrack, DrumSample> = {};
  const palette =
    groove.id === 'percussion' ? PERCUSSION_PALETTE : DRUM_PALETTE;
  const usedSounds = new Set<number>();
  const kick = new Set<number>([0]);
  const backbeat = new Set<number>();
  pulses.forEach(({ start, length }, index) => {
    if (index % 2 === 1) backbeat.add(start);
    if (groove.id === 'dance' || (index % 2 === 0 && chance(0.8)))
      kick.add(start);
    if ((groove.id === 'broken' || groove.id === 'funk') && chance(0.65)) {
      kick.add(start + length - pick([1, 2]));
    }
    if (groove.id === 'funk' && index % 2 === 1 && chance(0.35)) {
      backbeat.add(start + length - 1);
    }
  });
  if (!backbeat.size) backbeat.add(steps - unitSteps);
  // Preserve the metronome's group boundaries in odd and compound meters.
  groupStarts.forEach((start, index) => {
    if (index % 2 === 0) kick.add(start);
  });
  const pulseSpacing = groove.id === 'funk' ? pick([1, 2]) : pick([2, 2, 4]);
  const pulseOffset = pick([0, 0, 1]);
  const accentOffset = pick([1, 2]);

  tracks.forEach((id, index) => {
    const role = Math.min(index, 4);
    const available = palette[role].filter(note => !usedSounds.has(note));
    const note = pick(available.length ? available : palette[role]);
    usedSounds.add(note);
    samples[id] = { kind: 'builtin', note };
    const hit = (step: number) => {
      if (step >= 0 && step < steps) pattern[id][step] = true;
    };
    if (role === 0) {
      kick.forEach(hit);
    } else if (role === 1) {
      backbeat.forEach(hit);
    } else if (role === 2) {
      for (let step = pulseOffset; step < steps; step += pulseSpacing)
        hit(step);
      hit(0);
    } else if (role === 3) {
      pulses.forEach(({ start, length }, pulse) => {
        if (pulse % 2 === 0 || groove.id === 'dance') {
          hit(start + Math.min(accentOffset, length - 1));
        }
      });
    } else {
      // Additional rows answer the main pulse sparsely instead of stacking full patterns.
      const pulse = pulses[(index - 4) % pulses.length];
      hit(pulse.start + Math.min(pulse.length - 1, 1 + (index % 3)));
      if (chance(0.35)) hit(steps - 1 - ((index - 4) % Math.min(4, steps)));
    }
  });
  const openHat = tracks.find(id => {
    const sample = samples[id];
    return sample.kind === 'builtin' && sample.note === 46;
  });
  if (openHat) {
    tracks.forEach(id => {
      const sample = samples[id];
      if (sample.kind === 'builtin' && [42, 44].includes(sample.note)) {
        pattern[id] = pattern[id].map(
          (hit, step) => hit && !pattern[openHat][step],
        );
      }
    });
  }

  const effects = defaultEffects('drums');
  effects.equalizer = {
    enabled: true,
    low: between(0, 2),
    mid: between(-3, 0),
    high: between(-2, 2),
  };
  effects.compressor = {
    enabled: true,
    threshold: between(-18, -12),
    ratio: pick([2, 2.5, 3]),
  };
  effects.reverb = {
    enabled: true,
    mix: between(8, 18),
    tone: between(35, 75) * 100,
  };
  if (finish === 'Тёплый') {
    effects.distortion = {
      enabled: true,
      drive: between(5, 14),
      tone: between(30, 55) * 100,
    };
    effects.equalizer.high = -between(1, 3);
  } else if (finish === 'Ритмичное эхо') {
    const quarter = 60000 / bpm;
    const divisions = [0.25, 0.5, 0.75].filter(
      value => quarter * value >= 50 && quarter * value <= 1000,
    );
    effects.delay = {
      enabled: true,
      time: Math.round(quarter * pick(divisions)),
      feedback: between(12, 26),
      mix: between(8, 16),
    };
  } else if (finish === 'Мягкий хорус') {
    effects.chorus = {
      enabled: true,
      rate: between(3, 9) / 10,
      depth: pick([1, 1.5, 2]),
      mix: between(6, 12),
    };
  }
  return {
    pattern,
    samples,
    effects,
    description: `${groove.label}. Обработка: ${finish.toLowerCase()}.`,
  };
};
